```bash
# curl: check retry-after and backoff hint
curl -i -X POST https://api.redwood.ai/v1/generate \
  -H "Authorization: Bearer $REDWOOD_KEY" \
  -d '{"model":"large-v1","prompt":"hello"}'
# if 429 returned, read the Retry-After header and wait that many seconds + jitter
```
```python
# python lifeboat: exponential backoff, honor Retry-After, model fallback
import time
from redwood import RedwoodClient
c = RedwoodClient(api_key="$REDWOOD_KEY")

def lifeboat(prompt):
    backoff = 0.5
    for attempt in range(6):
        resp = c.generate(prompt, model="large-v1", timeout=10)
        if resp.status_code == 200:
            return resp
        if resp.status_code == 429:
            ra = resp.headers.get('retry-after')
            wait = float(ra) if ra else backoff
            time.sleep(wait + (0.1 * attempt))
            backoff = min(backoff * 2, 8)
            continue
        if resp.status_code in (502, 504) and attempt == 3:
            # try a smaller/quantized model as a lifeboat
            return c.generate(prompt, model="small-quant-v1", max_tokens=256)
    raise RuntimeError('request failed after retries')
```
```js
// node lifeboat: backoff + Retry-After + fallback
const {RedwoodClient} = require('@redwood/inference')
const client = new RedwoodClient({ apiKey: process.env.REDWOOD_KEY })

async function lifeboat(prompt){
  let backoff = 500
  for(let i=0;i<6;i++){
    try{
      const res = await client.generate({ model: 'large-v1', prompt, timeout: 10000 })
      if(res.ok) return res
      if(res.status === 429){
        const ra = res.headers.get('retry-after')
        const wait = ra ? (parseInt(ra)*1000 + Math.random()*300) : backoff
        await new Promise(r=>setTimeout(r, wait))
        backoff = Math.min(backoff*2, 10000)
        continue
      }
    }catch(e){
      if(i===3) return client.generate({ model: 'small-quant-v1', prompt, max_tokens:256 })
    }
  }
  throw new Error('lifeboat exhausted')
}
```
Jordan (eng-runtime): solid. suggest adding one sentence about when to prefer caching (high repeat ratio) vs fallback (latency-sensitive). also note that fallback reduces latency but can change output quality and cost profile.
